        self.items.append(item)  # Add an item to the end of the list

    def pop(self):
        if not self.is_empty():
            return self.items.pop()  # Remove and return the last item from the list
        else:
            raise IndexError("The stack is empty")

    def peek(self):
        if not self.is_empty():
            return self.items[-1]  # Return the last item from the list without removing it
        else:
